// Normalize Notion pages into flat task objects for calendar sync.
// EDIT THESE to match your Notion database:
const P = { title: 'Task', date: 'Due date', status: 'Status', direction: 'Direction', eventId: 'Google Event ID' };
const CLOSED = ['done', 'canceled', 'cancelled', 'failed', 'failed / canceled'];
const ZONE = 'Europe/Prague'; // your IANA time zone

const staticData = $getWorkflowStaticData('global');
const state = staticData.syncState || {};
const kinds = staticData.kinds || {};
const plain = (arr) => Array.isArray(arr)
  ? arr.map(t => t.plain_text || (t.text && t.text.content) || '').join('')
  : '';

return $input.all().map(item => {
  const page = item.json;
  const props = page.properties || {};
  const title = plain((props[P.title] || {}).title).trim() || 'Untitled';
  const dateObj = (props[P.date] || {}).date || null;
  const rawStart = dateObj ? dateObj.start : null;
  const rawEnd = dateObj ? dateObj.end : null;
  const hasDate = !!rawStart;
  const hasTime = hasDate && rawStart.includes('T');
  const isAllDay = hasDate && !hasTime;

  let start = null, end = null;
  if (hasTime) {
    const s = DateTime.fromISO(rawStart, { setZone: true }).setZone(ZONE);
    let e = (rawEnd && rawEnd.includes('T')) ? DateTime.fromISO(rawEnd, { setZone: true }).setZone(ZONE) : null;
    if (!e || !e.isValid || e <= s) e = s.plus({ hours: 1 });
    start = s.toISO();
    end = e.toISO();
  } else if (isAllDay) {
    // Google wants an EXCLUSIVE end date. Pinned to 12:00 UTC so the day never shifts.
    const startDate = rawStart.slice(0, 10);
    const lastRaw = rawEnd ? rawEnd.slice(0, 10) : startDate;
    const lastDate = lastRaw >= startDate ? lastRaw : startDate;
    start = startDate + 'T12:00:00.000Z';
    end = DateTime.fromISO(lastDate).plus({ days: 1 }).toISODate() + 'T12:00:00.000Z';
  }

  const statusProp = props[P.status] || {};
  const status = (statusProp.status && statusProp.status.name) || (statusProp.select && statusProp.select.name) || '';
  const direction = ((props[P.direction] || {}).select || {}).name || '';
  const eventId = plain((props[P.eventId] || {}).rich_text).trim();
  const isClosed = CLOSED.includes(status.toLowerCase());
  const pageUrl = page.url || '';

  // Events cannot be converted in place between timed and all-day: change of kind = delete + recreate.
  const kind = isAllDay ? 'allday' : 'timed';
  const prevKind = kinds[page.id] || 'timed';
  const kindChanged = !!eventId && hasDate && prevKind !== kind;

  const coreFingerprint = [title, start || '', end || '', status, direction, pageUrl, kind].join('|');
  const unchanged = state[page.id] === coreFingerprint + '|' + (eventId ? '1' : '0');
  const description = 'Notion: ' + pageUrl + (direction ? '\n' + direction : '');

  return { json: { pageId: page.id, title, start, end, hasDate, hasTime, isAllDay, kind, kindChanged,
    status, isClosed, direction, eventId, pageUrl, description, coreFingerprint, unchanged } };
});

// Store what the page looks like after a successful sync, so the
// re-trigger caused by our own Notion write is skipped.
const t = $('Normalize Task').item.json;
const sd = $getWorkflowStaticData('global');
sd.syncState = sd.syncState || {};
sd.kinds = sd.kinds || {};
const expectedHasEvent = t.hasDate; // closed tasks keep their event
sd.syncState[t.pageId] = t.coreFingerprint + '|' + (expectedHasEvent ? '1' : '0');
if (t.kindChanged) {
  // Event was deleted so it can be recreated in the other form. State says 'has event'
  // while Notion has no ID now, so the next poll recreates it.
} else if (expectedHasEvent) {
  sd.kinds[t.pageId] = t.kind;
} else {
  delete sd.kinds[t.pageId];
}
return { json: { pageId: t.pageId, title: t.title, synced: true, hasEvent: expectedHasEvent, kind: t.kind } };

// The calendar event was missing: forget the stored state so the next poll can recreate it.
const t = $('Normalize Task').item.json;
const sd = $getWorkflowStaticData('global');
sd.syncState = sd.syncState || {};
sd.kinds = sd.kinds || {};
delete sd.syncState[t.pageId];
delete sd.kinds[t.pageId];
return { json: { pageId: t.pageId, title: t.title, eventIdCleared: true } };

// Reverse sync step 1: read the Notion page id from the event description
// ('Notion: <url>') and normalise the event time.
const ZONE = 'Europe/Prague'; // your IANA time zone
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  if (!e || e.status === 'cancelled') continue;
  const m = String(e.description || '').match(/Notion: *[^ ]*?([0-9a-f]{32})/i);
  if (!m) continue; // not an event made by this workflow
  const sRaw = e.start && (e.start.dateTime || e.start.date);
  const eRaw = e.end && (e.end.dateTime || e.end.date);
  if (!sRaw || !eRaw) continue;
  const timed = !!(e.start && e.start.dateTime);
  let g;
  if (timed) {
    g = { kind: 'timed',
      start: DateTime.fromISO(sRaw, { setZone: true }).setZone(ZONE).toISO(),
      end: DateTime.fromISO(eRaw, { setZone: true }).setZone(ZONE).toISO() };
  } else {
    const s = sRaw.slice(0, 10);
    const last = DateTime.fromISO(eRaw.slice(0, 10)).minus({ days: 1 }).toISODate();
    g = { kind: 'allday', start: s, end: last >= s ? last : s };
  }
  out.push({ json: { pageId: m[1], eventId: e.id, title: e.summary || '', ...g } });
}
return out;

// Reverse sync step 2: does Google differ from Notion? Google wins here.
const P = { date: 'Due date', status: 'Status' }; // same names as in Normalize Task
const g = $('Parse Google Event').item.json;
const page = $json || {};
const props = page.properties;
const skip = (why) => ({ json: { changed: false, why, pageId: g.pageId } });
if (!props || page.archived || page.in_trash) return skip('page missing');
const d = (props[P.date] || {}).date;
if (!d || !d.start) return skip('no date in Notion');
const nStart = d.start, nEnd = d.end;
const nTimed = nStart.includes('T');
let same = false;
if (g.kind === 'timed' && nTimed) {
  const s = DateTime.fromISO(nStart, { setZone: true });
  let e = (nEnd && nEnd.includes('T')) ? DateTime.fromISO(nEnd, { setZone: true }) : null;
  if (!e || e <= s) e = s.plus({ hours: 1 });
  same = s.toMillis() === DateTime.fromISO(g.start).toMillis() && e.toMillis() === DateTime.fromISO(g.end).toMillis();
} else if (g.kind === 'allday' && !nTimed) {
  const ns = nStart.slice(0, 10);
  const nl = nEnd ? nEnd.slice(0, 10) : ns;
  same = ns === g.start && (nl >= ns ? nl : ns) === g.end;
}
if (same) return skip('already equal'); // this check is what prevents loops
const LOCAL = "yyyy-MM-dd'T'HH:mm:ss";
const notionDate = g.kind === 'timed'
  ? { start: DateTime.fromISO(g.start, { setZone: true }).toFormat(LOCAL), end: DateTime.fromISO(g.end, { setZone: true }).toFormat(LOCAL), timed: true }
  : { start: g.start, end: g.end !== g.start ? g.end : '', timed: false };
const sd = $getWorkflowStaticData('global');
sd.kinds = sd.kinds || {};
sd.kinds[g.pageId] = g.kind;
return { json: { changed: true, pageId: g.pageId, title: g.title, notionDate, hasEnd: !!notionDate.end } };
